var body = $input.first().json.body;
var company = (body.company || '').trim();
var slug = company.toLowerCase()
  .replace(/[^a-z0-9\s]/g, '')
  .trim()
  .replace(/\s+/g, '-');
return [{ json: {
  company: company,
  slug: slug,
  redisKey: 'company:dossier:' + slug,
  jobId: body.jobId || '',
  jobTitle: body.jobTitle || '',
  linkedinUrl: body.linkedinUrl || ''
}}];

var prep = $('Prepare Request').first().json;
var raw = Object.values($input.first().json)[0];
var dossier = null, isStale = true, exists = false;

if (raw) {
  try {
    dossier = typeof raw === 'string' ? JSON.parse(raw) : raw;
    exists = true;
    var lastUpdated = dossier.lastUpdated ? new Date(dossier.lastUpdated) : null;
    var daysSince = lastUpdated ? (new Date() - lastUpdated) / 86400000 : 999;
    isStale = daysSince > 30;
  } catch(e) { isStale = true; }
}

return [{ json: {
  company: prep.company,
  slug: prep.slug,
  redisKey: prep.redisKey,
  jobId: prep.jobId,
  jobTitle: prep.jobTitle,
  linkedinUrl: prep.linkedinUrl,
  dossier: dossier,
  exists: exists,
  isStale: isStale,
  cacheHit: exists && !isStale
}}];

var input = $input.first().json;
var dossier = JSON.parse(JSON.stringify(input.dossier));
if (!dossier.jobsApplied) dossier.jobsApplied = [];

var alreadyAdded = dossier.jobsApplied.some(function(j) { return j.jobId === input.jobId; });
if (!alreadyAdded && input.jobId) {
  dossier.jobsApplied.push({
    jobId: input.jobId,
    title: input.jobTitle || 'Unknown',
    linkedinUrl: input.linkedinUrl || '',
    date: new Date().toISOString().slice(0, 10)
  });
}

return [{ json: {
  company: input.company,
  slug: input.slug,
  redisKey: input.redisKey,
  dossierJson: JSON.stringify(dossier),
  dossier: dossier,
  source: 'cache'
}}];

var https = require('https');
var fs = require('fs');
var input = $input.first().json;
var slug = input.slug;

var config = {};
try { config = JSON.parse(fs.readFileSync('/home/node/.n8n/ai-config.json', 'utf8')); } catch(e) {}
var liAt = config.li_at || '';

function httpGet(hostname, path, headers) {
  return new Promise(function(resolve, reject) {
    var opts = { hostname: hostname, port: 443, path: path, method: 'GET',
      headers: headers || { 'User-Agent': 'Mozilla/5.0' } };
    var req = https.request(opts, function(res) {
      var chunks = [];
      res.on('data', function(d) { chunks.push(d.toString()); });
      res.on('end', function() { resolve({ status: res.statusCode, text: chunks.join('') }); });
    });
    req.on('error', reject);
    req.end();
  });
}

var linkedinData = {
  employeeCount: 'Unknown',
  industry: 'Unknown',
  description: '',
  linkedinUrl: 'https://www.linkedin.com/company/' + slug + '/'
};

try {
  var headers = { 'User-Agent': 'Mozilla/5.0', 'Accept': 'text/html', 'Accept-Language': 'en-US,en;q=0.9' };
  if (liAt) headers['Cookie'] = 'li_at=' + liAt;
  var result = await httpGet('www.linkedin.com', '/company/' + slug + '/about/', headers);
  if (result.status === 200) {
    var html = result.text;
    var empMatch = html.match(/"employeeCountRange":\{"start":(\d+),"end":(\d+)\}/);
    if (empMatch) linkedinData.employeeCount = empMatch[1] + '-' + empMatch[2] + ' employees';
    var indMatch = html.match(/"industryName":"([^"]+)"/);
    if (indMatch) linkedinData.industry = indMatch[1];
    var descMatch = html.match(/"description":"([^"]{10,500})"/);
    if (descMatch) linkedinData.description = descMatch[1].replace(/\\n/g, ' ');
  }
} catch(e) { linkedinData.fetchError = e.message; }

return [{ json: Object.assign({}, input, { linkedinData: linkedinData }) }];

var https = require('https');
