try { config = JSON.parse(fs.readFileSync('/home/node/.n8n/ai-config.json', 'utf8')); } catch(e) {}
var tavilyKey = config.tavily_api_key || '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';

function tavilySearch(query) {
  return new Promise(function(resolve, reject) {
    var body = JSON.stringify({
      api_key: tavilyKey, query: query, max_results: 5, include_answer: true
    });
    var bodyLen = typeof Buffer !== 'undefined' ? Buffer.byteLength(body, 'utf8') : body.length;
    var opts = {
      hostname: 'api.tavily.com', port: 443, path: '/search', method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Content-Length': bodyLen }
    };
    var req = https.request(opts, function(res) {
      var chunks = [];
      res.on('data', function(d) { chunks.push(d.toString()); });
      res.on('end', function() {
        try { resolve(JSON.parse(chunks.join(''))); }
        catch(e) { resolve({ results: [], answer: '' }); }
      });
    });
    req.on('error', function(e) { resolve({ results: [], answer: '', error: e.message }); });
    req.write(body);
    req.end();
  });
}

var tavilyData = { culture: null, news: null, error: null };

if (tavilyKey) {
  try {
    var cultureRes = await tavilySearch('"' + company + '" company culture engineering team size employees');
    var newsRes = await tavilySearch('"' + company + '" company news funding 2025 2026');
    tavilyData.culture = {
      answer: cultureRes.answer || '',
      results: (cultureRes.results || []).slice(0, 3).map(function(r) {
        return { title: r.title, url: r.url, snippet: (r.content || '').slice(0, 300) };
      })
