      answer: newsRes.answer || '',
      results: (newsRes.results || []).slice(0, 3).map(function(r) {
        return { title: r.title, url: r.url, snippet: (r.content || '').slice(0, 300) };
      })
    };
  } catch(e) { tavilyData.error = e.message; }
} else {
  tavilyData.error = 'No tavily_api_key found in ai-config.json';
}

return [{ json: Object.assign({}, input, { tavilyData: tavilyData }) }];

