      exaSearch({ query: company + ' company', category: 'company', numResults: 3, type: 'auto' }),
      exaSearch({ query: '"' + company + '" news funding 2025 2026', category: 'news', numResults: 5, contents: { text: { maxCharacters: 300 } } })
    ]);
    var companyRes = results[0];
    var newsRes = results[1];
    if (companyRes.status === 200 && companyRes.data.results && companyRes.data.results.length) {
      exaData.company = { results: companyRes.data.results.slice(0, 3).map(function(r) {
        return { title: r.title || '', url: r.url || '', snippet: (r.text || r.summary || '').slice(0, 500) };
      })};
    } else if (companyRes.status !== 200) {
      exaData.error = 'Company search HTTP ' + companyRes.status;
    }
    if (newsRes.status === 200 && newsRes.data.results && newsRes.data.results.length) {
      exaData.news = { results: newsRes.data.results.slice(0, 5).map(function(r) {
        return { title: r.title || '', url: r.url || '', date: r.publishedDate || '', snippet: (r.text || '').slice(0, 300) };
      })};
    }
  } catch(e) { exaData.error = e.message; }
} else { exaData.error = 'No exa_api_key configured'; }

return [{ json: Object.assign({}, input, { exaData: exaData }) }];

