var fs = require('fs');

var config = {};
try { config = JSON.parse(fs.readFileSync('/home/node/.n8n/ai-config.json', 'utf8')); } catch(e) {}

// ── CONFIG ───────────────────────────────────────────────────────────────────
var CLAUDE_KEY = config.claude_api_key || '';
var CLAUDE_MODEL = config.claude_model || 'claude-opus-4-5-20251101';
var OLLAMA_MODEL = config.fallback_model || 'llama3.2';
var OLLAMA_HOST = config.ollama_host || 'host.docker.internal';
var OLLAMA_PORT = parseInt(config.ollama_port || '11434');
// ────────────────────────────────────────────────────────────────────────────

var input = $input.first().json;
var company = input.company;
var slug = input.slug;
var jobId = input.jobId;
var jobTitle = input.jobTitle;
var linkedinUrl = input.linkedinUrl;
var linkedinData = input.linkedinData || {};
var tavilyData = input.tavilyData || {};

// Build research context
var ctx = '';
if (linkedinData.description) ctx += 'LinkedIn description: ' + linkedinData.description + '\n\n';
if (linkedinData.industry && linkedinData.industry !== 'Unknown') ctx += 'Industry (LinkedIn): ' + linkedinData.industry + '\n';
if (linkedinData.employeeCount && linkedinData.employeeCount !== 'Unknown') ctx += 'Employee count: ' + linkedinData.employeeCount + '\n\n';
if (tavilyData.culture && tavilyData.culture.answer) ctx += 'Culture research: ' + tavilyData.culture.answer + '\n\n';
if (tavilyData.news && tavilyData.news.answer) ctx += 'Recent news: ' + tavilyData.news.answer + '\n\n';
if (tavilyData.culture && tavilyData.culture.results) {
  tavilyData.culture.results.forEach(function(r) { ctx += r.title + ': ' + r.snippet + '\n'; });
}

function makeRequest(hostname, port, path, headers, body, useHttp) {
  return new Promise(function(resolve, reject) {
    var opts = { hostname: hostname, port: port, path: path, method: 'POST', headers: headers };
    var lib = useHttp ? http : https;
    var req = lib.request(opts, function(res) {
      var chunks = [];
      res.on('data', function(d) { chunks.push(d.toString()); });
      res.on('end', function() { resolve({ status: res.statusCode, text: chunks.join('') }); });
    });
    req.on('error', reject);
    req.write(body);
    req.end();
  });
}

async function generate(systemPrompt, userPrompt) {
  if (CLAUDE_KEY) {
    try {
      var cb = JSON.stringify({
        model: CLAUDE_MODEL, max_tokens: 1024, system: systemPrompt,
        messages: [{ role: 'user', content: userPrompt }]
      });
      var cbLen = typeof Buffer !== 'undefined' ? Buffer.byteLength(cb, 'utf8') : cb.length;
      var r = await makeRequest('api.anthropic.com', 443, '/v1/messages', {
        'Content-Type': 'application/json', 'x-api-key': CLAUDE_KEY,
        'anthropic-version': '2023-06-01', 'Content-Length': cbLen
      }, cb, false);
      if (r.status === 200) {
        var p = JSON.parse(r.text);
        return { text: p.content[0].text, model: CLAUDE_MODEL };
      }
    } catch(e) {}
  }
  var ob = JSON.stringify({ model: OLLAMA_MODEL, prompt: systemPrompt + '\n\n' + userPrompt, stream: false });
  var obLen = typeof Buffer !== 'undefined' ? Buffer.byteLength(ob, 'utf8') : ob.length;
  var r = await makeRequest(OLLAMA_HOST, OLLAMA_PORT, '/api/generate', {
    'Content-Type': 'application/json', 'Content-Length': obLen
  }, ob, true);
  var p = JSON.parse(r.text);
  return { text: p.response, model: OLLAMA_MODEL };
}

var SYSTEM = 'You are a company research assistant. Given research data, produce a structured JSON dossier about a company. Respond with ONLY valid JSON, no markdown, no explanation.';
var PROMPT = 'Company: ' + company + '\n\nResearch data:\n' + (ctx || 'No research data available.') + '\n\nProduce a JSON object with exactly these fields:\n{\n  "industry": "primary industry category",\n  "size": "employee range e.g. 50-200 employees",\n  "stage": "e.g. Series B, public, bootstrapped, unknown",\n  "hq": "City, State/Country or unknown",\n  "remote": "remote or hybrid or on-site or unknown",\n  "cultureSignals": ["array of keywords"],\n  "recentNews": ["array of news items as strings"],\n  "glassdoorSignals": ["any sentiment signals from search results"],\n  "researchNotes": "2-3 sentence narrative summary"\n}\n\nOutput ONLY the JSON object, no markdown.';

var fields = { industry:'Unknown', size:'Unknown', stage:'Unknown', hq:'Unknown', remote:'unknown',
  cultureSignals:[], recentNews:[], glassdoorSignals:[], researchNotes:'' };
var usedModel = OLLAMA_MODEL;

try {
  var result = await generate(SYSTEM, PROMPT);
  usedModel = result.model;
  var raw = result.text.trim()
    .replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/\s*```$/i, '');
  Object.assign(fields, JSON.parse(raw));
} catch(e) {
  fields.researchNotes = 'Error generating dossier: ' + e.message;
}

var today = new Date().toISOString().slice(0, 10);
var jobsApplied = [];
if (jobId) jobsApplied.push({ jobId: jobId, title: jobTitle || 'Unknown', linkedinUrl: linkedinUrl || '', date: today });

var sources = tavilyData.error ? ['linkedin'] : ['tavily', 'linkedin'];
sources.push('ai:' + usedModel);

var dossier = Object.assign({ company: company, slug: slug }, fields, {
  linkedinUrl: linkedinData.linkedinUrl || 'https://www.linkedin.com/company/' + slug + '/',
  jobsApplied: jobsApplied,
  lastUpdated: today,
  dataSourced: sources
});

return [{ json: {
  company: company, slug: slug, redisKey: input.redisKey,
  dossierJson: JSON.stringify(dossier), dossier: dossier
}}];

var http = require('http');
var input = $input.first().json;
var dossier = input.dossier;
var slug = input.slug;

var CHROMA_HOST = 'host.docker.internal';
var CHROMA_PORT = 8000;
var COLLECTION = 'company-dossiers';

function chromaReq(method, path, body) {
  return new Promise(function(resolve, reject) {
    var bodyStr = body ? JSON.stringify(body) : '';
    var bodyLen = typeof Buffer !== 'undefined' ? Buffer.byteLength(bodyStr, 'utf8') : bodyStr.length;
    var opts = {
      hostname: CHROMA_HOST, port: CHROMA_PORT, path: '/api/v1' + path, method: method,
      headers: { 'Content-Type': 'application/json', 'Content-Length': bodyLen }
    };
    var req = http.request(opts, function(res) {
      var chunks = [];
      res.on('data', function(d) { chunks.push(d.toString()); });
      res.on('end', function() {
        try { resolve({ status: res.statusCode, data: JSON.parse(chunks.join('')) }); }
        catch(e) { resolve({ status: res.statusCode, data: chunks.join('') }); }
      });
    });
    req.on('error', function(e) { resolve({ status: 0, data: null, error: e.message }); });
    if (bodyStr) req.write(bodyStr);
    req.end();
  });
}

var chromaResult = { success: false, error: null, collectionId: null };

try {
  // Use get_or_create directly — avoids brittle list-then-find pattern
  // and works with both old (array) and new ({collections:[]}) Chroma API formats
  var createRes = await chromaReq('POST', '/collections', { name: COLLECTION, get_or_create: true });
  if ((createRes.status === 200 || createRes.status === 201) && createRes.data && createRes.data.id) {
    chromaResult.collectionId = createRes.data.id;
  } else {
    chromaResult.error = 'get_or_create failed: HTTP ' + createRes.status + ' — ' + JSON.stringify(createRes.data).slice(0, 200);
  }
} catch(e) {
  chromaResult.error = 'Collection error: ' + e.message;
}

if (chromaResult.collectionId) {
  try {
    var docText = [
      dossier.company, dossier.industry, dossier.size, dossier.stage, dossier.hq,
      (dossier.cultureSignals || []).join(', '),
      (dossier.recentNews || []).join('. '),
      dossier.researchNotes
    ].filter(Boolean).join('\n');
    var upsertRes = await chromaReq('POST', '/collections/' + chromaResult.collectionId + '/upsert', {
      ids: [slug],
      documents: [docText],
      metadatas: [{ company: dossier.company, slug: slug, industry: dossier.industry || '', lastUpdated: dossier.lastUpdated || '' }]
    });
    chromaResult.success = upsertRes.status === 200 || upsertRes.status === 201;
    if (!chromaResult.success) chromaResult.error = 'Upsert HTTP ' + upsertRes.status + ': ' + JSON.stringify(upsertRes.data).slice(0, 200);
  } catch(e) {
    chromaResult.error = e.message;
  }
}

return [{ json: Object.assign({}, input, { chromaResult: { success: chromaResult.success, error: chromaResult.error } }) }];

var https = require('https');
var fs = require('fs');
var input = $input.first().json;
var company = input.company;

// CONFIG
var config = {};
try { config = JSON.parse(fs.readFileSync('/home/node/.n8n/ai-config.json', 'utf8')); } catch(e) {}
var exaKey = config.exa_api_key || '28d2d097-2afa-4adf-a183-4df94ea07cbb';

function exaSearch(payload) {
  return new Promise(function(resolve) {
    var body = JSON.stringify(payload);
    var bodyLen = typeof Buffer !== 'undefined' ? Buffer.byteLength(body, 'utf8') : body.length;
    var opts = {
      hostname: 'api.exa.ai', port: 443, path: '/search', method: 'POST',
      headers: { 'Content-Type': 'application/json', 'x-api-key': exaKey, 'Content-Length': bodyLen }
    };
    var req = https.request(opts, function(res) {
      var chunks = [];
      res.on('data', function(d) { chunks.push(d.toString()); });
      res.on('end', function() {
        try { resolve({ status: res.statusCode, data: JSON.parse(chunks.join('')) }); }
        catch(e) { resolve({ status: res.statusCode, data: { results: [] } }); }
      });
    });
    req.on('error', function(e) { resolve({ status: 0, data: { results: [] }, error: e.message }); });
    req.write(body);
    req.end();
  });
}

var exaData = { company: null, news: null, error: null };

if (exaKey) {
  try {
    var results = await Promise.all([
      exaSearch({ query: company + ' company', category: 'company', numResults: 3, type: 'auto' }),
      exaSearch({ query: '"' + company + '" news funding 2025 2026', category: 'news', numResults: 5, contents: { text: { maxCharacters: 300 } } })
    ]);
    var companyRes = results[0];
    var newsRes = results[1];
    if (companyRes.status === 200 && companyRes.data.results && companyRes.data.results.length) {
      exaData.company = { results: companyRes.data.results.slice(0, 3).map(function(r) {
        return { title: r.title || '', url: r.url || '', snippet: (r.text || r.summary || '').slice(0, 500) };
      })};
    } else if (companyRes.status !== 200) {
      exaData.error = 'Company search HTTP ' + companyRes.status;
    }
    if (newsRes.status === 200 && newsRes.data.results && newsRes.data.results.length) {
      exaData.news = { results: newsRes.data.results.slice(0, 5).map(function(r) {
        return { title: r.title || '', url: r.url || '', date: r.publishedDate || '', snippet: (r.text || '').slice(0, 300) };
      })};
    }
  } catch(e) { exaData.error = e.message; }
} else { exaData.error = 'No exa_api_key configured'; }

return [{ json: Object.assign({}, input, { exaData: exaData }) }];
